"""Esquema de partida de etapa 4 para instalaciones nuevas y actualización aditiva."""

DDL = ('\nCREATE TABLE IF NOT EXISTS clientes (\n\tid VARCHAR(36) NOT NULL, \n\tnombre VARCHAR(200) NOT NULL, \n\tes_ejemplo BOOLEAN NOT NULL, \n\tPRIMARY KEY (id)\n)\n\n', '\nCREATE TABLE IF NOT EXISTS planillas (\n\tid VARCHAR(36) NOT NULL, \n\tcodigo VARCHAR(60) NOT NULL, \n\tversion VARCHAR(30) NOT NULL, \n\tsistema_tipo VARCHAR(12) NOT NULL, \n\thuella VARCHAR(64) NOT NULL, \n\tdefinicion JSON NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (codigo, version)\n)\n\n', "\nCREATE TABLE IF NOT EXISTS usuarios (\n\tid VARCHAR(36) NOT NULL, \n\tlogin VARCHAR(80) NOT NULL, \n\tnombre VARCHAR(120) NOT NULL, \n\tclave_hash BYTEA NOT NULL, \n\trol VARCHAR(12) NOT NULL, \n\tactivo BOOLEAN NOT NULL, \n\tcreado_en TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tCHECK (rol IN ('admin','tecnico')), \n\tUNIQUE (login)\n)\n\n", '\nCREATE TABLE IF NOT EXISTS versiones_esquema (\n\tnumero SERIAL NOT NULL, \n\taplicada_en TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (numero)\n)\n\n', '\nCREATE TABLE IF NOT EXISTS sesiones_usuario (\n\ttoken_hash VARCHAR(64) NOT NULL, \n\tusuario_id VARCHAR(36) NOT NULL, \n\tvence_en TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (token_hash), \n\tFOREIGN KEY(usuario_id) REFERENCES usuarios (id)\n)\n\n', 'CREATE INDEX IF NOT EXISTS ix_sesiones_usuario_usuario_id ON sesiones_usuario (usuario_id)', '\nCREATE TABLE IF NOT EXISTS sistemas (\n\tid VARCHAR(36) NOT NULL, \n\tcliente_id VARCHAR(36) NOT NULL, \n\ttipo VARCHAR(12) NOT NULL, \n\tdesignacion VARCHAR(200) NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(cliente_id) REFERENCES clientes (id)\n)\n\n', 'CREATE INDEX IF NOT EXISTS ix_sistemas_cliente_id ON sistemas (cliente_id)', '\nCREATE TABLE IF NOT EXISTS usuarios_clientes (\n\tusuario_id VARCHAR(36) NOT NULL, \n\tcliente_id VARCHAR(36) NOT NULL, \n\tPRIMARY KEY (usuario_id, cliente_id), \n\tFOREIGN KEY(usuario_id) REFERENCES usuarios (id), \n\tFOREIGN KEY(cliente_id) REFERENCES clientes (id)\n)\n\n', "\nCREATE TABLE IF NOT EXISTS cargas (\n\tid VARCHAR(36) NOT NULL, \n\tsistema_id VARCHAR(36) NOT NULL, \n\tplanilla_id VARCHAR(36) NOT NULL, \n\tcreada_por_id VARCHAR(36), \n\testado VARCHAR(20) NOT NULL, \n\tdatos JSON NOT NULL, \n\trevision INTEGER NOT NULL, \n\tcreada_en TIMESTAMP WITH TIME ZONE NOT NULL, \n\tactualizada_en TIMESTAMP WITH TIME ZONE NOT NULL, \n\tfinalizada_en TIMESTAMP WITH TIME ZONE, \n\temitida_en TIMESTAMP WITH TIME ZONE, \n\tpdf BYTEA, \n\tpdf_sha256 VARCHAR(64), \n\tPRIMARY KEY (id), \n\tCHECK (estado IN ('borrador','finalizada','emitida')), \n\tFOREIGN KEY(sistema_id) REFERENCES sistemas (id), \n\tFOREIGN KEY(planilla_id) REFERENCES planillas (id), \n\tFOREIGN KEY(creada_por_id) REFERENCES usuarios (id)\n)\n\n", 'CREATE INDEX IF NOT EXISTS ix_cargas_planilla_id ON cargas (planilla_id)', 'CREATE INDEX IF NOT EXISTS ix_cargas_sistema_id ON cargas (sistema_id)', '\nCREATE TABLE IF NOT EXISTS firmas_carga (\n\tcarga_id VARCHAR(36) NOT NULL, \n\ttecnico_png BYTEA, \n\tresponsable_png BYTEA, \n\tPRIMARY KEY (carga_id), \n\tFOREIGN KEY(carga_id) REFERENCES cargas (id)\n)\n\n', '\nCREATE TABLE IF NOT EXISTS registros_acceso (\n\tid VARCHAR(36) NOT NULL, \n\tusuario_id VARCHAR(36), \n\tfecha TIMESTAMP WITH TIME ZONE NOT NULL, \n\tevento VARCHAR(40) NOT NULL, \n\truta VARCHAR(200) NOT NULL, \n\tmetodo VARCHAR(10) NOT NULL, \n\testado_http INTEGER NOT NULL, \n\tcliente_id VARCHAR(36), \n\tcarga_id VARCHAR(36), \n\tplanilla_codigo VARCHAR(60), \n\tdestinatario VARCHAR(254), \n\tlogin_huella VARCHAR(64), \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(usuario_id) REFERENCES usuarios (id), \n\tFOREIGN KEY(cliente_id) REFERENCES clientes (id), \n\tFOREIGN KEY(carga_id) REFERENCES cargas (id)\n)\n\n', 'CREATE INDEX IF NOT EXISTS ix_registros_acceso_fecha ON registros_acceso (fecha)', 'CREATE INDEX IF NOT EXISTS ix_registros_acceso_login_huella ON registros_acceso (login_huella)', 'CREATE INDEX IF NOT EXISTS ix_registros_acceso_usuario_id ON registros_acceso (usuario_id)', '\nCREATE TABLE IF NOT EXISTS revisiones_carga (\n\tid VARCHAR(36) NOT NULL, \n\tcarga_id VARCHAR(36) NOT NULL, \n\tnumero INTEGER NOT NULL, \n\tevento VARCHAR(40) NOT NULL, \n\tdatos JSON NOT NULL, \n\tfirmas_huellas JSON, \n\tactor_id VARCHAR(36), \n\tactor VARCHAR(120) NOT NULL, \n\tfecha TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (carga_id, numero), \n\tFOREIGN KEY(carga_id) REFERENCES cargas (id), \n\tFOREIGN KEY(actor_id) REFERENCES usuarios (id)\n)\n\n', 'CREATE INDEX IF NOT EXISTS ix_revisiones_carga_carga_id ON revisiones_carga (carga_id)')


def upgrade(connection):
    for statement in DDL:
        connection.exec_driver_sql(statement)

    from pathlib import Path
    import runpy
    from sqlalchemy import text
    directory=Path(__file__).resolve().parent
    for number,filename in ((1,None),(2,"002_firmas_etapa3.py"),(3,"003_usuarios_etapa4.py")):
        if connection.execute(text("SELECT numero FROM versiones_esquema WHERE numero=:n"),{"n":number}).first() is None:
            if filename:runpy.run_path(str(directory/filename))["upgrade"](connection)
            connection.execute(text("INSERT INTO versiones_esquema (numero, aplicada_en) VALUES (:n,CURRENT_TIMESTAMP)"),{"n":number})
